 "content": "from collections import deque


def transform(grid):
    h, w = len(grid), len(grid[0])
    ones = {(r, c) for r in range(h) for c in range(w) if grid[r][c] == 1}
    if not ones:
        return [row[:] for row in grid]

    # The 1-colored copy fixes the silhouette and the stack's alignment.
    seed = next(iter(ones))
    q, shape = deque([seed]), {seed}
    while q:
        r, c = q.popleft()
        for nr, nc in ((r-1,c),(r+1,c),(r,c-1),(r,c+1)):
            if (nr, nc) in ones and (nr, nc) not in shape:
                shape.add((nr, nc))
                q.append((nr, nc))
    r0, r1 = min(r for r, _ in shape), max(r for r, _ in shape)
    c0, c1 = min(c for _, c in shape), max(c for _, c in shape)
    points = [(r-r0, c-c0) for r, c in shape]
    sh = r1-r0+1

    # The palette key is a repeated row of adjacent colors, separate from
    # the silhouette. Select the most frequent repeated nonzero row pattern.
    rows = {}
    for r, row in enumerate(grid):
        pattern = tuple((c, v) for c, v in enumerate(row) if v != 0)
        if pattern:
            rows.setdefault(pattern, []).append(r)
    candidates = [(len(rs), len(pattern), pattern, rs) for pattern, rs in rows.items()
                  if len(rs) >= 2 and all(not any((rr, cc) in shape for cc, _ in pattern) for rr in rs)]
    if not candidates:
        # Fall back to most common repeated row pattern if the colored key
        # touches/intersects the silhouette's rows.
        candidates = [(len(rs), len(pattern), pattern, rs) for pattern, rs in rows.items() if len(rs) >= 2]
    _, _, pattern, key_rows = max(candidates)
    colors = []
    for _, color in pattern:
        if color not in colors:
            colors.append(color)
    anchor = colors.index(1)
    top = r0 - anchor * sh

    out = [[0] * w for _ in range(h)]
    for i, color in enumerate(colors):
        yy = top + i * sh
        for dy, dx in points:
            y, x = yy + dy, c0 + dx
            if 0 <= y < h and 0 <= x < w:
                out[y][x] = color
    return out


